import { defineModule } from "@wolfstar/kit";

/**
 * The options of the module: none yet. The `subcommandsAdvanced` key of `stars.config` is reserved for them.
 */
export type SubcommandsAdvancedModuleOptions = Record<string, never>;

/**
 * The Stars module: listing `@wolfstar/plugin-subcommands-advanced/module` in `modules` in `stars.config` registers
 * the subcommands plugin. The module itself takes no options; the package's behaviour is still configured through
 * `ClientOptions.subcommandsAdvanced` (for example `nameCommandsAutogenerated`).
 *
 * @remarks
 * The module owns the `subcommandsAdvanced` key of `stars.config`, which takes no options for now.
 *
 * @example
 * ```ts
 * // stars.config.ts
 * export default defineConfig({
 *   modules: ['@wolfstar/plugin-subcommands-advanced/module'],
 * });
 * ```
 */
export default defineModule<SubcommandsAdvancedModuleOptions>({
  meta: {
    name: "@wolfstar/plugin-subcommands-advanced",
    configKey: "subcommandsAdvanced",
    compatibility: { framework: ">=6.1.0" },
  },
  setup(options, ctx) {
    ctx.addPlugin({ from: "@wolfstar/plugin-subcommands-advanced/plugin", options });
  },
});

declare module "@wolfstar/schema" {
  interface StarsConfig {
    subcommandsAdvanced?: SubcommandsAdvancedModuleOptions;
  }
}
